/// <summary>
/// CB521_ExciseRegister
/// </summary>
[DataContractAttribute]
class METExciseLodgementUpdateContract
{
    ItemId              itemId;
    InventSiteId        siteId;
    InventTransType     referenceId;

}

Method.Source:
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public InventTransType  parmReferenceId(InventTransType     _referenceId = referenceId)
    {
        referenceId = _referenceId;

        return referenceId;
    }

    /// <summary>
    /// Parameter method for itemId
    /// </summary>
    /// <param name = "_itemId">Item id reference</param>
    /// <returns>ItemId</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public ItemId parmItemId(ItemId     _itemId = itemId)
    {
        itemId = _itemId;

        return itemId;
    }

    /// <summary>
    /// Parameter method for siteId
    /// </summary>
    /// <param name = "_siteId">Site id reference</param>
    /// <returns>InventSiteId</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public InventSiteId parmSiteId(InventSiteId     _siteId = siteId)
    {
        siteId = _siteId;

        return siteId;
    }
